Using the frozen Brief and approved skeleton, write a complete ExperimentalMusicSpec. Preserve the skeleton's identity and section plan while realizing concrete notes, rests, velocities and useful CC. Output only the complete spec JSON.


FROZEN BRIEF:
{
  "id": "l1-song-hook",
  "level": "L1",
  "title": "Open-window song hook",
  "purpose": "An original eight-bar instrumental hook that could anchor an optimistic indie-pop song.",
  "duration_seconds": 18,
  "section_plan": [
    "hook: 8 bars"
  ],
  "style": [
    "indie pop",
    "clear diatonic harmony",
    "singable"
  ],
  "mood": [
    "hopeful",
    "open",
    "human"
  ],
  "must_include": [
    "four-bar harmonic question and answer",
    "recognizable two-bar melodic cell",
    "bass supports chord inversions"
  ],
  "must_avoid": [
    "quoted melodies",
    "constant eighth-note melody",
    "four identical bars"
  ],
  "instrument_roles": [
    "piano harmony",
    "lead melody",
    "bass"
  ],
  "delivery": [
    "8 bars",
    "3 tracks",
    "complete note endings"
  ],
  "score_focus": [
    "harmony",
    "melody",
    "brief match"
  ],
  "mode_a": true
}

SKELETON:
{"title":"Open-window song hook","tempo_map":[{"bar":1,"bpm":112}],"key_map":[{"bar":1,"key":"C major"}],"sections":[{"id":"hook","start_bar":1,"bars":8}],"track_plan":[{"id":"piano","name":"Piano Harmony","role":"harmony","register":{"low":48,"high":84},"instrument_hint":"acoustic grand piano","section_jobs":[{"section_id":"hook","intent":"Play clear diatonic chords with gentle rhythmic placement, using inversions to lead voice smoothly; leave space for melody.","density":"medium"}]},{"id":"melody","name":"Lead Melody","role":"melody","register":{"low":60,"high":79},"instrument_hint":"vocal-like synth or plucked timbre","section_jobs":[{"section_id":"hook","intent":"State the two-bar melodic cell, then answer with a contrasting continuation; include rests and a lift in the second half.","density":"sparse"}]},{"id":"bass","name":"Bass","role":"bass","register":{"low":28,"high":48},"instrument_hint":"electric bass","section_jobs":[{"section_id":"hook","intent":"Outline chord roots and inversions with sustained or short notes, locking with the harmonic rhythm and not doubling melody.","density":"sparse"}]}],"motif_strategy":"A recognizable two-bar melodic cell (e.g., ascending third then stepwise return) is stated in bars 1-2 and varied in bars 5-6; bars 3-4 and 7-8 provide contrasting answers, avoiding constant eighth-note motion.","harmony_strategy":"Four-bar harmonic question (I-vi-IV-V or similar) followed by a four-bar answer with a cadential extension or inversion shift; piano uses smooth voice leading and occasional inversions to support melody.","groove_strategy":"Piano provides a light syncopated or off-beat chord stab pattern while bass plays root-fifth or arpeggiated inversions on downbeats; overall groove is relaxed and forward-moving without dominating the melody."}

EXPERIMENTAL MUSIC SPEC SCHEMA:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://auto-studio.local/q0/experimental-music-spec.schema.json",
  "title": "ExperimentalMusicSpec",
  "type": "object",
  "additionalProperties": false,
  "required": ["title", "tempo_map", "key_map", "sections", "tracks"],
  "properties": {
    "title": {"type": "string", "minLength": 1, "maxLength": 120},
    "tempo_map": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/tempo_change"}},
    "key_map": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/key_change"}},
    "sections": {"type": "array", "minItems": 1, "maxItems": 24, "items": {"$ref": "#/$defs/section"}},
    "tracks": {"type": "array", "minItems": 1, "maxItems": 16, "items": {"$ref": "#/$defs/track"}}
  },
  "$defs": {
    "time_signature": {
      "type": "object", "additionalProperties": false,
      "required": ["numerator", "denominator"],
      "properties": {
        "numerator": {"type": "integer", "minimum": 1, "maximum": 32},
        "denominator": {"enum": [1, 2, 4, 8, 16, 32]}
      }
    },
    "tempo_change": {
      "type": "object", "additionalProperties": false,
      "required": ["bar", "bpm", "time_signature"],
      "properties": {
        "bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "bpm": {"type": "number", "minimum": 30, "maximum": 300},
        "time_signature": {"$ref": "#/$defs/time_signature"}
      }
    },
    "key_change": {
      "type": "object", "additionalProperties": false,
      "required": ["bar", "tonic", "mode"],
      "properties": {
        "bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "tonic": {"type": "string", "minLength": 1, "maxLength": 8},
        "mode": {"type": "string", "minLength": 1, "maxLength": 32}
      }
    },
    "section": {
      "type": "object", "additionalProperties": false,
      "required": ["id", "label", "start_bar", "length_bars", "intent"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,47}$"},
        "label": {"type": "string", "minLength": 1, "maxLength": 80},
        "start_bar": {"type": "integer", "minimum": 1, "maximum": 1024},
        "length_bars": {"type": "integer", "minimum": 1, "maximum": 128},
        "intent": {"type": "string", "minLength": 1, "maxLength": 240}
      }
    },
    "register": {
      "type": "object", "additionalProperties": false,
      "required": ["low", "high"],
      "properties": {
        "low": {"type": "integer", "minimum": 0, "maximum": 127},
        "high": {"type": "integer", "minimum": 0, "maximum": 127}
      }
    },
    "note": {
      "type": "object", "additionalProperties": false,
      "required": ["beat", "duration", "pitch", "velocity"],
      "properties": {
        "beat": {"type": "number", "minimum": 0},
        "duration": {"type": "number", "exclusiveMinimum": 0},
        "pitch": {"type": "integer", "minimum": 0, "maximum": 127},
        "velocity": {"type": "integer", "minimum": 1, "maximum": 127}
      }
    },
    "cc": {
      "type": "object", "additionalProperties": false,
      "required": ["beat", "controller", "value"],
      "properties": {
        "beat": {"type": "number", "minimum": 0},
        "controller": {"type": "integer", "minimum": 0, "maximum": 127},
        "value": {"type": "integer", "minimum": 0, "maximum": 127}
      }
    },
    "region": {
      "type": "object", "additionalProperties": false,
      "required": ["section_id", "notes", "cc"],
      "properties": {
        "section_id": {"type": "string", "minLength": 1, "maxLength": 48},
        "notes": {"type": "array", "maxItems": 2048, "items": {"$ref": "#/$defs/note"}},
        "cc": {"type": "array", "maxItems": 1024, "items": {"$ref": "#/$defs/cc"}}
      }
    },
    "track": {
      "type": "object", "additionalProperties": false,
      "required": ["id", "name", "role", "register", "instrument_hint", "regions"],
      "properties": {
        "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9_-]{0,47}$"},
        "name": {"type": "string", "minLength": 1, "maxLength": 80},
        "role": {"type": "string", "minLength": 1, "maxLength": 80},
        "register": {"$ref": "#/$defs/register"},
        "instrument_hint": {"type": "string", "minLength": 1, "maxLength": 120},
        "regions": {"type": "array", "maxItems": 48, "items": {"$ref": "#/$defs/region"}}
      }
    }
  }
}

